#!/usr/bin/env python3
"""FS3 v182 - the damage on capital ships, reworked (Silvio on v181: huge
shapeless holes that look slapped on).

    Tears     No holes to the stars any more. From 70 % down a ship gets
              several narrow tears along her plating, small, the same size
              on any ship (big hulls get more, not bigger): dark inside,
              frames showing across, cracks off the ends, a lit lip. Fresh
              ones glow and cool to a few embers; fire glows inside.
    Marks     Small streaks of carbon scoring where hits land, the same
              size on any ship.
    Space     Jets of burning gas, venting air, smoke and sparks fly free:
              they leave with the ship's velocity plus the push of the gas
              and go straight on - nothing rises, nothing falls, nothing
              drifts. A ship that turns or changes speed leaves them behind.
    More      Small secondary explosions below 50 %, blue-white arcs across
              the tears below 30 %. Lights, craters and engine flicker as
              before.

Needs v181. Edits src/20_render.js and src/60_effects.js in place, and
writes the updated fieldsim.js. Run assemble.py afterwards.
"""
import base64
import os
import sys

if "function dmgK" not in open("src/20_render.js", encoding="utf-8").read():
    sys.exit("Abbruch: erst v181 einspielen.")
if "function dmgEmit" in open("src/20_render.js", encoding="utf-8").read():
    sys.exit("Abbruch: v182 ist schon eingespielt.")

F = {}
def load(p):
    if p not in F: F[p] = open(p, encoding="utf-8").read()
def rep(p, old, new, count=1):
    load(p)
    n = F[p].count(old)
    if n != count:
        sys.exit("Abbruch (%s): Suchtext %d-mal gefunden, erwartet %d.\n%s" % (p, n, count, old[:200]))
    F[p] = F[p].replace(old, new)

